"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[87743],{37637(e,a,o){o.r(a),o.d(a,{assets:()=>c,contentTitle:()=>n,default:()=>u,frontMatter:()=>t,metadata:()=>s,toc:()=>m});const s=JSON.parse('{"id":"learning/courses/practical-near-term-qc/introduction","title":"Introduction","description":"Uma introdu\xe7\xe3o a um curso sobre aplica\xe7\xf5es pr\xe1ticas da computa\xe7\xe3o qu\xe2ntica.","source":"@site/i18n/pt/docusaurus-plugin-content-docs/current/learning/courses/practical-near-term-qc/introduction.mdx","sourceDirName":"learning/courses/practical-near-term-qc","slug":"/learning/courses/practical-near-term-qc/introduction","permalink":"/learning/courses/practical-near-term-qc/introduction","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/practical-near-term-qc/introduction.mdx","tags":[],"version":"current","frontMatter":{"description":"Uma introdu\xe7\xe3o a um curso sobre aplica\xe7\xf5es pr\xe1ticas da computa\xe7\xe3o qu\xe2ntica.","notebook_path":"learning/courses/practical-near-term-qc/introduction.ipynb","sidebar_label":"Introduction","title":"Introduction"},"sidebar":"tutorialsSidebar","previous":{"title":"Overview","permalink":"/learning/courses/practical-near-term-qc/"},"next":{"title":"Vis\xe3o geral","permalink":"/learning/courses/quantum-business-foundations/"}}');var r=o(74848),i=o(28453);const t={description:"Uma introdu\xe7\xe3o a um curso sobre aplica\xe7\xf5es pr\xe1ticas da computa\xe7\xe3o qu\xe2ntica.",notebook_path:"learning/courses/practical-near-term-qc/introduction.ipynb",sidebar_label:"Introduction",title:"Introduction"},n="Introdu\xe7\xe3o \xe0 computa\xe7\xe3o qu\xe2ntica pr\xe1tica de curto prazo {#introduction-to-practical-near-term-quantum-computing}",c={},m=[{value:"Para que os computadores qu\xe2nticos podem ser \xfateis",id:"what-quantum-computers-might-be-useful-for",level:2},{value:"Utilidade e vantagem qu\xe2ntica de curto prazo",id:"near-term-quantum-utility-and-advantage",level:2},{value:"Uma breve base em teoria da complexidade",id:"a-brief-foundation-in-complexity-theory",level:2},{value:"Da teoria da complexidade \xe0 evid\xeancia pr\xe1tica",id:"from-complexity-theory-to-practical-evidence",level:2},{value:"\xc1reas de aplica\xe7\xe3o e estudos de caso do curso",id:"application-areas-and-course-case-studies",level:2},{value:"Simula\xe7\xe3o hamiltoniana",id:"hamiltonian-simulation",level:3},{value:"Otimiza\xe7\xe3o",id:"optimization",level:3},{value:"Aprendizado de m\xe1quina qu\xe2ntico",id:"quantum-machine-learning",level:3},{value:"Equa\xe7\xf5es diferenciais parciais",id:"partial-differential-equations",level:3},{value:"Conclus\xe3o",id:"conclusion",level:2}];function d(e){const a={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:["\n",(0,r.jsx)(a.header,{children:(0,r.jsx)(a.h1,{id:"introduction-to-practical-near-term-quantum-computing",children:"Introdu\xe7\xe3o \xe0 computa\xe7\xe3o qu\xe2ntica pr\xe1tica de curto prazo"})}),"\n",(0,r.jsx)(a.p,{children:"Desde que os computadores qu\xe2nticos foram propostos pela primeira vez, h\xe1 mais de quatro d\xe9cadas, a pergunta tem sido: at\xe9 onde essa nova abordagem poderia levar os limites da computa\xe7\xe3o? A ci\xeancia da computa\xe7\xe3o te\xf3rica nos deu algumas respostas empolgantes. Computadores qu\xe2nticos poderiam fatorar inteiros grandes de forma drasticamente mais r\xe1pida que os melhores m\xe9todos cl\xe1ssicos conhecidos, acelerar buscas n\xe3o estruturadas e simular sistemas qu\xe2nticos de maneira mais natural. No entanto, muitas dessas ideias pressupunham um futuro computador qu\xe2ntico tolerante a falhas e em larga escala."}),"\n",(0,r.jsx)(a.p,{children:"A tecnologia ainda n\xe3o alcan\xe7ou todos esses objetivos te\xf3ricos, mas est\xe1 melhorando rapidamente. Hoje, pesquisadores podem usar processadores qu\xe2nticos para explorar problemas cient\xedficos e industriais reais. Neste curso, voc\xea vai ter experi\xeancia pr\xe1tica com algumas das aplica\xe7\xf5es mais promissoras. Vamos estimar propriedades de baixa energia de um modelo molecular complexo, simular a din\xe2mica de uma teoria de gauge em rede e explorar como um problema de portf\xf3lio financeiro pode ser mapeado para um computador qu\xe2ntico. Tamb\xe9m vamos olhar para \xe1reas mais recentes, nas quais s\xf3 come\xe7amos a entender o que os computadores qu\xe2nticos podem oferecer, incluindo aprendizado de m\xe1quina qu\xe2ntico (QML) e abordagens qu\xe2nticas para equa\xe7\xf5es diferenciais parciais (EDPs)."}),"\n",(0,r.jsx)(a.p,{children:"Muitos dos exemplos deste curso s\xe3o pequenos o bastante para serem resolvidos por um computador cl\xe1ssico. Isso \xe9 intencional. O objetivo \xe9 dar a voc\xea uma experi\xeancia concreta com todo o processo de usar um computador qu\xe2ntico para resolver um problema do mundo real. Alguns exemplos representam problemas para os quais a vantagem qu\xe2ntica pode surgir em escalas muito maiores. Em outros exemplos, usamos um m\xe9todo simplificado para que os detalhes de implementa\xe7\xe3o n\xe3o escondam a ideia qu\xe2ntica central."}),"\n",(0,r.jsx)(a.p,{children:"Ao final do curso, voc\xea deve ter uma vis\xe3o geral das principais aplica\xe7\xf5es qu\xe2nticas e uma intui\xe7\xe3o de por que os computadores qu\xe2nticos podem ser \xfateis em determinadas \xe1reas. Voc\xea vai conhecer t\xe9cnicas comuns para representar problemas em computadores qu\xe2nticos, aprender como m\xe9todos qu\xe2nticos e cl\xe1ssicos trabalham juntos e come\xe7ar a reconhecer quais ferramentas e compromissos importam para diferentes tipos de problemas."}),"\n",(0,r.jsx)(a.p,{children:"Nesta primeira li\xe7\xe3o, vamos abordar alguns dos conceitos fundamentais e a terminologia que ajudam a entender, em alto n\xedvel, as aplica\xe7\xf5es da computa\xe7\xe3o qu\xe2ntica, e apresentar uma vis\xe3o geral das principais \xe1reas de aplica\xe7\xe3o que a comunidade cient\xedfica vem explorando ativamente."}),"\n",(0,r.jsx)(a.h2,{id:"what-quantum-computers-might-be-useful-for",children:"Para que os computadores qu\xe2nticos podem ser \xfateis"}),"\n",(0,r.jsx)(a.p,{children:"Os computadores qu\xe2nticos costumam ser vistos como concorrentes dos computadores cl\xe1ssicos, mas uma forma mais adequada de pensar neles \xe9 como recursos especializados dentro de fluxos de trabalho cl\xe1ssicos maiores. A pergunta importante, ent\xe3o, \xe9 quais partes de uma computa\xe7\xe3o s\xe3o especialmente adequadas ao hardware qu\xe2ntico. A resposta mais intuitiva vem de problemas que j\xe1 s\xe3o qu\xe2nticos, como o comportamento de mol\xe9culas, materiais e campos qu\xe2nticos. Um processador qu\xe2ntico pode representar e manipular estados qu\xe2nticos diretamente, enquanto os recursos necess\xe1rios para uma descri\xe7\xe3o cl\xe1ssica geral crescem exponencialmente com o tamanho do sistema."}),"\n",(0,r.jsx)(a.p,{children:"O caso \xe9 mais sutil para problemas com entradas e sa\xeddas cl\xe1ssicas, mas ainda h\xe1 boas raz\xf5es para explor\xe1-los. Problemas de otimiza\xe7\xe3o s\xe3o muito comuns e economicamente importantes, ent\xe3o at\xe9 uma melhoria modesta na qualidade da solu\xe7\xe3o ou no tempo de execu\xe7\xe3o pode ser valiosa. Algoritmos qu\xe2nticos tamb\xe9m podem oferecer novas formas de explorar espa\xe7os de solu\xe7\xf5es complicados ou de aproveitar a estrutura de certas classes de problemas. O aprendizado de m\xe1quina qu\xe2ntico tem forte motiva\xe7\xe3o te\xf3rica para certos problemas com entradas cl\xe1ssicas, incluindo classifica\xe7\xe3o estruturada e processamento de conjuntos de dados enormes. No entanto, se esses resultados podem se traduzir em vantagem pr\xe1tica com dados cl\xe1ssicos do mundo real continua sendo uma quest\xe3o em aberto. Equa\xe7\xf5es diferenciais parciais descrevem muitos sistemas importantes em ci\xeancia, engenharia e finan\xe7as, e algoritmos qu\xe2nticos podem melhorar a escala de certas simula\xe7\xf5es de alta dimens\xe3o e de grandes problemas de \xe1lgebra linear."}),"\n",(0,r.jsx)(a.p,{children:"Em todas essas tr\xeas \xe1reas, por\xe9m, o custo de preparar as entradas cl\xe1ssicas, executar a computa\xe7\xe3o qu\xe2ntica e extrair uma resposta cl\xe1ssica \xfatil pode superar o benef\xedcio da etapa qu\xe2ntica. Vamos ter esses desafios pr\xe1ticos em mente ao explorar como os m\xe9todos qu\xe2nticos s\xe3o aplicados em cada \xe1rea."}),"\n",(0,r.jsx)(a.h2,{id:"near-term-quantum-utility-and-advantage",children:"Utilidade e vantagem qu\xe2ntica de curto prazo"}),"\n",(0,r.jsx)(a.p,{children:"Este curso n\xe3o trata especificamente de vantagem qu\xe2ntica, mas \xe9 inevit\xe1vel discuti-la. A motiva\xe7\xe3o fundamental por tr\xe1s das aplica\xe7\xf5es qu\xe2nticas \xe9 usar recursos qu\xe2nticos para ampliar o que os computadores cl\xe1ssicos conseguem fazer sozinhos: produzir resultados mais precisos, chegar a solu\xe7\xf5es mais r\xe1pido ou resolver problemas que, de outra forma, seriam inacess\xedveis. Os termos relacionados a seguir nos ajudam a falar com clareza sobre o progresso que vemos:"}),"\n",(0,r.jsxs)(a.ul,{children:["\n",(0,r.jsxs)(a.li,{children:["\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Speedup qu\xe2ntico:"})," \xc0 medida que o tamanho do problema aumenta, o tempo exigido por um m\xe9todo qu\xe2ntico cresce de forma mais favor\xe1vel que o do melhor m\xe9todo cl\xe1ssico relevante para a mesma tarefa."]}),"\n"]}),"\n",(0,r.jsxs)(a.li,{children:["\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Vantagem qu\xe2ntica:"})," Uma computa\xe7\xe3o habilitada por recursos qu\xe2nticos supera as melhores abordagens cl\xe1ssicas relevantes em uma tarefa bem definida e com uma m\xe9trica significativa. Em vez de um marco \xfanico e permanente, a vantagem qu\xe2ntica \xe9 uma fronteira em evolu\xe7\xe3o, que se desloca \xe0 medida que os m\xe9todos qu\xe2nticos e cl\xe1ssicos melhoram."]}),"\n"]}),"\n",(0,r.jsxs)(a.li,{children:["\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Utilidade qu\xe2ntica:"})," Uma computa\xe7\xe3o qu\xe2ntica contribui para um resultado cient\xedfico ou t\xe9cnico \xfatil. Ela opera em uma escala, profundidade e precis\xe3o al\xe9m do que a simula\xe7\xe3o cl\xe1ssica por for\xe7a bruta consegue na pr\xe1tica, sem necessariamente superar o melhor m\xe9todo cl\xe1ssico."]}),"\n"]}),"\n",(0,r.jsxs)(a.li,{children:["\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Algoritmo de curto prazo:"})," Um algoritmo projetado para os processadores qu\xe2nticos atuais, que usa profundidades de circuito limitadas e frequentemente depende de p\xf3s-processamento cl\xe1ssico e de mitiga\xe7\xe3o de erros, em vez de corre\xe7\xe3o de erros qu\xe2ntica completa."]}),"\n"]}),"\n",(0,r.jsxs)(a.li,{children:["\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Computa\xe7\xe3o qu\xe2ntica tolerante a falhas:"})," No futuro, a computa\xe7\xe3o qu\xe2ntica usar\xe1 corre\xe7\xe3o de erros qu\xe2ntica para proteger qubits l\xf3gicos ao longo de toda a computa\xe7\xe3o. Quando as taxas de erro f\xedsico est\xe3o abaixo do limiar de toler\xe2ncia a falhas, recursos adicionais de corre\xe7\xe3o de erros podem suprimir os erros l\xf3gicos at\xe9 o n\xedvel que computa\xe7\xf5es longas e confi\xe1veis exigem. A toler\xe2ncia a falhas torna poss\xedveis algoritmos muito mais profundos, incluindo implementa\xe7\xf5es em larga escala do algoritmo de Shor."]}),"\n"]}),"\n",(0,r.jsxs)(a.li,{children:["\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Toler\xe2ncia a falhas inicial:"})," Toler\xe2ncia a falhas significa que os erros s\xe3o suprimidos, n\xe3o eliminados por completo. Em sistemas tolerantes a falhas iniciais, os erros l\xf3gicos residuais ainda precisam ser considerados, e a profundidade dos circuitos confi\xe1veis continua limitada."]}),"\n"]}),"\n",(0,r.jsxs)(a.li,{children:["\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Algoritmo heur\xedstico:"})," Um m\xe9todo projetado para encontrar uma boa solu\xe7\xe3o na pr\xe1tica, sem garantir a resposta \xf3tima nem um tempo de execu\xe7\xe3o espec\xedfico."]}),"\n"]}),"\n"]}),"\n",(0,r.jsx)(a.h2,{id:"a-brief-foundation-in-complexity-theory",children:"Uma breve base em teoria da complexidade"}),"\n",(0,r.jsx)(a.p,{children:"Em algumas \xe1reas de aplica\xe7\xe3o, temos uma forte raz\xe3o te\xf3rica para esperar que um computador qu\xe2ntico possa ter vantagem. Para entender de onde vem essa confian\xe7a, precisamos de um pouco de vocabul\xe1rio da teoria da complexidade."}),"\n",(0,r.jsx)(a.p,{children:"A teoria da complexidade estuda como os recursos necess\xe1rios para resolver um problema crescem \xe0 medida que o problema fica maior. Ela nos d\xe1 um mapa \xfatil de onde um speedup qu\xe2ntico pode ser poss\xedvel. Alguns termos s\xe3o especialmente importantes neste curso:"}),"\n",(0,r.jsxs)(a.ul,{children:["\n",(0,r.jsxs)(a.li,{children:["\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"P:"})," Problemas que um computador cl\xe1ssico consegue resolver de forma eficiente, ou seja, em que os recursos necess\xe1rios crescem de forma polinomial com o tamanho do problema."]}),"\n"]}),"\n",(0,r.jsxs)(a.li,{children:["\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"NP:"})," Problemas para os quais \xe9 poss\xedvel verificar eficientemente uma solu\xe7\xe3o proposta, mesmo que encontrar essa solu\xe7\xe3o possa ser muito dif\xedcil."]}),"\n"]}),"\n",(0,r.jsxs)(a.li,{children:["\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"NP-dif\xedcil:"})," Problemas que s\xe3o pelo menos t\xe3o dif\xedceis quanto todo problema em NP. Um problema NP-dif\xedcil n\xe3o pertence necessariamente a NP. Muitos problemas de otimiza\xe7\xe3o s\xe3o NP-dif\xedceis."]}),"\n"]}),"\n",(0,r.jsxs)(a.li,{children:["\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"NP-completo:"})," Problemas que s\xe3o ao mesmo tempo NP-dif\xedceis e pertencentes a NP. S\xe3o os problemas de decis\xe3o mais dif\xedceis dentro de NP."]}),"\n"]}),"\n",(0,r.jsxs)(a.li,{children:["\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"BQP:"})," Problemas que um computador qu\xe2ntico consegue resolver de forma eficiente com probabilidade de erro limitada."]}),"\n"]}),"\n"]}),"\n",(0,r.jsx)(a.p,{children:"Algumas rela\xe7\xf5es entre essas categorias s\xe3o conhecidas. P est\xe1 contido tanto em NP quanto em BQP, porque um problema que pode ser resolvido eficientemente em um computador cl\xe1ssico tamb\xe9m pode ser verificado classicamente e resolvido em um computador qu\xe2ntico. Outras rela\xe7\xf5es continuam em aberto. N\xe3o sabemos se P \xe9 igual a NP nem se NP est\xe1 contido em BQP. No entanto, os pesquisadores geralmente acreditam que P \xe9 menor que NP e BQP, e que os computadores qu\xe2nticos n\xe3o conseguem resolver eficientemente todo problema NP-completo. Em termos simples, um computador qu\xe2ntico n\xe3o \xe9 uma caixa m\xe1gica que resolve instantaneamente todo problema dif\xedcil."}),"\n",(0,r.jsx)(a.p,{children:"Os argumentos mais fortes baseados em complexidade a favor da computa\xe7\xe3o qu\xe2ntica se aplicam a tipos espec\xedficos de problemas. O algoritmo de Shor escala de forma drasticamente melhor que os melhores algoritmos cl\xe1ssicos conhecidos para fatora\xe7\xe3o e logaritmos discretos, embora n\xe3o se tenha provado que a fatora\xe7\xe3o est\xe1 fora de P. A simula\xe7\xe3o qu\xe2ntica geral tamb\xe9m tem uma base te\xf3rica s\xf3lida. Alguns problemas de simula\xe7\xe3o qu\xe2ntica s\xe3o BQP-completos, o que significa que resolv\xea-los eficientemente de forma cl\xe1ssica equivaleria a simular eficientemente qualquer computa\xe7\xe3o qu\xe2ntica. Uma simula\xe7\xe3o cl\xe1ssica eficiente assim \xe9 altamente implaus\xedvel, e essa \xe9 uma das raz\xf5es pelas quais a simula\xe7\xe3o hamiltoniana qu\xe2ntica \xe9 considerada uma \xe1rea de aplica\xe7\xe3o t\xe3o promissora."}),"\n",(0,r.jsx)(a.p,{children:"Algumas EDPs de alta dimens\xe3o podem ser reduzidas a problemas de sistemas lineares BQP-completos, o que nos d\xe1 uma forte raz\xe3o para esperar um speedup qu\xe2ntico quando entradas e sa\xeddas podem ser tratadas com efici\xeancia. O QML tem exemplos semelhantes: algumas tarefas envolvendo dados qu\xe2nticos s\xe3o BQP-completas, e alguns modelos qu\xe2nticos conseguem gerar amostras dif\xedceis de reproduzir classicamente."}),"\n",(0,r.jsx)(a.p,{children:"O caso \xe9 menos direto para a otimiza\xe7\xe3o. N\xe3o se espera que computadores qu\xe2nticos resolvam eficientemente problemas NP-dif\xedceis arbitr\xe1rios, mas eles ainda podem ajudar com problemas estruturados, inst\xe2ncias espec\xedficas ou etapas particulares de um fluxo de trabalho de otimiza\xe7\xe3o. O algoritmo de Grover, por exemplo, oferece um speedup quadr\xe1tico para busca n\xe3o estruturada. Essa \xe9 uma melhoria significativa, mesmo que a raiz quadrada de um espa\xe7o de busca astronomicamente grande ainda possa ser astron\xf4mica."}),"\n",(0,r.jsx)(a.h2,{id:"from-complexity-theory-to-practical-evidence",children:"Da teoria da complexidade \xe0 evid\xeancia pr\xe1tica"}),"\n",(0,r.jsx)(a.p,{children:"A teoria da complexidade pode nos dizer onde um speedup qu\xe2ntico pode ser poss\xedvel, mas geralmente n\xe3o consegue dizer como um m\xe9todo se comporta em um problema espec\xedfico ou em um computador qu\xe2ntico espec\xedfico. Muitos dos m\xe9todos usados no hardware atual s\xe3o heur\xedsticos. Eles s\xe3o projetados para encontrar boas respostas na pr\xe1tica, mas n\xe3o garantem a melhor resposta poss\xedvel nem um tempo de execu\xe7\xe3o espec\xedfico."}),"\n",(0,r.jsx)(a.p,{children:"Heur\xedsticas n\xe3o s\xe3o exclusivas da computa\xe7\xe3o qu\xe2ntica, e chamar um m\xe9todo de heur\xedstico n\xe3o significa que ele seja pouco confi\xe1vel ou pouco cient\xedfico. Otimiza\xe7\xe3o cl\xe1ssica, aprendizado de m\xe1quina e qu\xedmica computacional dependem fortemente de heur\xedsticas quando uma solu\xe7\xe3o exata seria cara demais. Uma heur\xedstica qu\xe2ntica pode oferecer uma nova forma de explorar um espa\xe7o de solu\xe7\xf5es, preparar estados \xfateis ou identificar candidatos promissores. Se ela funciona bem \xe9 uma quest\xe3o emp\xedrica: temos que execut\xe1-la e medir o resultado."}),"\n",(0,r.jsx)(a.p,{children:"Como as heur\xedsticas n\xe3o v\xeam com garantias de desempenho, n\xf3s as avaliamos usando uma m\xe9trica de sucesso clara, refer\xeancias cl\xe1ssicas fortes e testes em diferentes tamanhos de problema. Isso nos ajuda a ver onde um m\xe9todo funciona bem e como seu desempenho muda \xe0 medida que o problema cresce."}),"\n",(0,r.jsx)(a.h2,{id:"application-areas-and-course-case-studies",children:"\xc1reas de aplica\xe7\xe3o e estudos de caso do curso"}),"\n",(0,r.jsx)(a.p,{children:"Organizamos o curso em torno de quatro grandes \xe1reas de aplica\xe7\xe3o. Elas n\xe3o cobrem todos os usos poss\xedveis de um computador qu\xe2ntico, mas nos d\xe3o uma forma \xfatil de comparar onde est\xe3o os argumentos mais fortes e onde est\xe3o as quest\xf5es em aberto."}),"\n",(0,r.jsx)(a.h3,{id:"hamiltonian-simulation",children:"Simula\xe7\xe3o hamiltoniana"}),"\n",(0,r.jsx)(a.p,{children:"A simula\xe7\xe3o hamiltoniana inclui estimar energias, estudar propriedades qu\xedmicas e de materiais e modelar como sistemas qu\xe2nticos mudam ao longo do tempo. Ela abrange qu\xedmica, ci\xeancia de materiais, f\xedsica da mat\xe9ria condensada e f\xedsica de altas energias e nuclear. Nossos estudos de caso examinam um modelo de ferro-enxofre fortemente correlacionado usando diagonaliza\xe7\xe3o qu\xe2ntica baseada em amostras e simulam a din\xe2mica de h\xe1drons usando uma representa\xe7\xe3o em rede que respeita simetrias. S\xe3o dois exemplos de um campo muito maior, que tamb\xe9m inclui mecanismos de rea\xe7\xe3o, materiais magn\xe9ticos e outras din\xe2micas de muitos corpos."}),"\n",(0,r.jsx)(a.h3,{id:"optimization",children:"Otimiza\xe7\xe3o"}),"\n",(0,r.jsx)(a.p,{children:"A otimiza\xe7\xe3o aparece em toda parte, de finan\xe7as e log\xedstica a agendamento e sistemas de energia. \xc9 tamb\xe9m uma \xe1rea em que a vantagem \xe9 dif\xedcil de estabelecer, porque os solvers cl\xe1ssicos s\xe3o extremamente capazes e os mapeamentos qu\xe2nticos podem acrescentar um overhead custoso. Nosso estudo de caso usa a sele\xe7\xe3o de portf\xf3lio para explorar como um problema de otimiza\xe7\xe3o \xe9 representado, executado e avaliado, sem presumir que um computador qu\xe2ntico encontre automaticamente o \xf3timo exato."}),"\n",(0,r.jsx)(a.h3,{id:"quantum-machine-learning",children:"Aprendizado de m\xe1quina qu\xe2ntico"}),"\n",(0,r.jsx)(a.p,{children:"O aprendizado de m\xe1quina qu\xe2ntico investiga se circuitos qu\xe2nticos ou dados qu\xe2nticos podem melhorar uma tarefa de aprendizado. Quest\xf5es importantes incluem codifica\xe7\xe3o de dados, custo de treinamento, generaliza\xe7\xe3o e compara\xe7\xe3o com modelos cl\xe1ssicos fortes."}),"\n",(0,r.jsx)(a.h3,{id:"partial-differential-equations",children:"Equa\xe7\xf5es diferenciais parciais"}),"\n",(0,r.jsx)(a.p,{children:"Equa\xe7\xf5es diferenciais parciais descrevem sistemas como fluidos, calor e ondas. Algoritmos qu\xe2nticos podem acelerar partes de alguns fluxos de trabalho de EDPs, mas a prepara\xe7\xe3o dos dados e a extra\xe7\xe3o de uma resposta cl\xe1ssica \xfatil podem ser custos importantes. O estudo de caso espec\xedfico ainda est\xe1 em desenvolvimento."}),"\n",(0,r.jsx)(a.p,{children:"Nas li\xe7\xf5es seguintes, faremos as mesmas perguntas b\xe1sicas em cada \xe1rea: qual \xe9 o problema, por que a computa\xe7\xe3o qu\xe2ntica poderia ajudar, quais s\xe3o as limita\xe7\xf5es e o que a evid\xeancia realmente mostra? Vamos come\xe7ar pela simula\xe7\xe3o hamiltoniana, em que o pr\xf3prio problema \xe9 qu\xe2ntico."}),"\n",(0,r.jsx)(a.h2,{id:"conclusion",children:"Conclus\xe3o"}),"\n",(0,r.jsx)(a.p,{children:"Percorremos bastante ch\xe3o, mas a ideia principal \xe9 simples: computadores qu\xe2nticos s\xe3o ferramentas especializadas, e seu valor depende de usar o m\xe9todo qu\xe2ntico certo para o problema certo, ou para a parte certa de um problema maior. A simula\xe7\xe3o hamiltoniana tem a base te\xf3rica mais clara, a otimiza\xe7\xe3o tem um conjunto maduro de m\xe9todos heur\xedsticos e refer\xeancias, e o QML e as EDPs oferecem dire\xe7\xf5es promissoras que ainda est\xe3o se desenvolvendo."}),"\n",(0,r.jsx)(a.p,{children:"Nas li\xe7\xf5es seguintes, passaremos dessa vis\xe3o geral ampla para exemplos pr\xe1ticos. Para cada aplica\xe7\xe3o, perguntaremos qual problema estamos tentando resolver, que papel o computador qu\xe2ntico desempenha, como o resultado \xe9 interpretado e o que podemos aprender com ele. O objetivo \xe9 construir sua intui\xe7\xe3o sobre onde a computa\xe7\xe3o qu\xe2ntica pode ajudar e o que \xe9 preciso para transformar uma ideia promissora em uma computa\xe7\xe3o real."}),"\n"]})}function u(e={}){const{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,r.jsx)(a,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},28453(e,a,o){o.d(a,{R:()=>t,x:()=>n});var s=o(96540);const r={},i=s.createContext(r);function t(e){const a=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function n(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:t(e.components),s.createElement(i.Provider,{value:a},e.children)}}}]);